import {useCallback, useEffect, useRef, useState} from 'react';

import {selectedItemsGroupId} from '../constants';
import type {TrackerSelectGroup, TrackerSelectItemValueBase} from '../types';

export function useExpandedGroups<
    Value extends TrackerSelectItemValueBase = TrackerSelectItemValueBase,
>(
    groups?: TrackerSelectGroup<Value>[],
    resetExpandedStateOnGroupsChange = false,
    isGroupExpandedByDefault?: (group: TrackerSelectGroup<Value>) => boolean,
) {
    const [expandedGroups, setExpandedGroups] = useState<Record<string, boolean>>({
        [selectedItemsGroupId]: true,
    });
    const expandedGroupsRef = useRef<Record<string, boolean>>(expandedGroups);

    const handleExpandChange = useCallback((groupId: string, expanded: boolean) => {
        if (expandedGroupsRef.current[groupId] !== expanded) {
            expandedGroupsRef.current = {...expandedGroupsRef.current, [groupId]: expanded};
            setExpandedGroups(expandedGroupsRef.current);
        }
    }, []);

    useEffect(() => {
        if (!groups || !isGroupExpandedByDefault) return;

        for (const group of groups) {
            if (isGroupExpandedByDefault(group)) {
                handleExpandChange(group.id, true);
            } else {
                handleExpandChange(group.id, false);
            }
        }
    }, [groups, handleExpandChange, isGroupExpandedByDefault]);

    useEffect(() => {
        if (groups && resetExpandedStateOnGroupsChange) {
            setExpandedGroups({});
        }
    }, [resetExpandedStateOnGroupsChange, groups]);

    return {
        expandedGroups,
        expandedGroupsRef,
        handleExpandChange,
    };
}
